"""SRS 10 Nov UC015 Reset Password with a verification code (UC014)."""
import sys
from lib import *

reseed()
cnt = lambda q: int(sql(q))
anon = C()
email = sql("SELECT email FROM users WHERE username='stf001'")
login_ok = lambda pw: C().login('stf001', pw).status_code == 302
pg = anon.get('forgot_password.php')
ok('the page opens without signing in', pg.status_code == 200 and 'Request code' in pg.text and not errs(pg))
ok('POST without a CSRF token is refused (419)', anon.post('forgot_password.php', {'action': 'request_code', 'username': 'stf001', 'email': email}, csrf=False).status_code == 419)
r = anon.post('forgot_password.php', {'action': 'request_code', 'username': 'stf001', 'email': 'wrong@uis.edu.my'})
ok('a staff ID and e-mail that do not match: account not found (2.1), nothing is sent', 'account is not found' in r.text and cnt("SELECT COUNT(*) FROM email_log WHERE kind='verification'") == 0)
r = anon.post('forgot_password.php', {'action': 'request_code', 'username': 'nobody', 'email': email})
ok('an unknown staff ID: the same message', 'account is not found' in r.text)
sql("UPDATE users SET is_active=0 WHERE username='stf003'")
r = anon.post('forgot_password.php', {'action': 'request_code', 'username': 'stf003', 'email': sql("SELECT email FROM users WHERE username='stf003'")})
ok('an Inactive account cannot reset', 'account is not found' in r.text)
sql("UPDATE users SET is_active=1 WHERE username='stf003'")
r = anon.post('forgot_password.php', {'action': 'request_code', 'username': 'stf001', 'email': email})
ok('Request code: the code is e-mailed (logged) and step 2 asks for it', 'Verification code' in r.text and len(last_code(email)) == 6)
code = last_code(email)
r = anon.post('forgot_password.php', {'action': 'save', 'password': 'Newpass123', 'confirm_password': 'Newpass123'})
ok('the new password form cannot be reached without the code', login_ok('staff001@uis') and not login_ok('Newpass123'))
ok('trying to skip the code starts the flow again', 'Staff ID' in anon.get('forgot_password.php').text)
anon.post('forgot_password.php', {'action': 'request_code', 'username': 'stf001', 'email': email}); code = last_code(email)
r = anon.post('forgot_password.php', {'action': 'verify', 'code': '000000' if code != '000000' else '111111'}); ok('a wrong code: verification failed (3.1)', 'Verification failed' in r.text)
anon.post('forgot_password.php', {'action': 'resend'}); code = last_code(email)
ok('Resend code (A1): one code for the e-mail', cnt("SELECT COUNT(*) FROM verification_codes WHERE email='%s' AND purpose='reset'" % email) == 1)
r = anon.post('forgot_password.php', {'action': 'verify', 'code': code}); ok('the right code shows the new password form', 'New password' in r.text and 'name="confirm_password"' in r.text)
r = anon.post('forgot_password.php', {'action': 'save', 'password': 'Newpass123', 'confirm_password': 'Different123'}); ok('passwords that differ are refused (4.1)', 'do not match' in r.text and login_ok('staff001@uis'))
r = anon.post('forgot_password.php', {'action': 'save', 'password': 'short', 'confirm_password': 'short'}); ok('a weak password is refused', login_ok('staff001@uis'))
r = anon.post('forgot_password.php', {'action': 'save', 'password': 'Newpass123', 'confirm_password': 'Newpass123'})
ok('saved: the sign-in page with a success message', r.status_code == 302 and r.headers['Location'].endswith('login.php') and 'Your password was changed' in anon.get('login.php').text)
ok('the new password works, the old one does not', login_ok('Newpass123') and not login_ok('staff001@uis'))
ok('the code cannot be used again; the history log has it, without the password', cnt("SELECT COUNT(*) FROM verification_codes WHERE email='%s'" % email) == 0 and cnt("SELECT COUNT(*) FROM audit_log WHERE action='password_reset'") == 1 and cnt("SELECT COUNT(*) FROM audit_log WHERE reason LIKE '%Newpass123%'") == 0)
# a locked account is unlocked by a reset
sql("UPDATE users SET failed_attempts=3, locked_until=NOW() + INTERVAL 10 MINUTE WHERE username='drv001'")
a2 = C(); em = sql("SELECT email FROM users WHERE username='drv001'")
a2.post('forgot_password.php', {'action': 'request_code', 'username': 'drv001', 'email': em}); a2.post('forgot_password.php', {'action': 'verify', 'code': last_code(em)})
a2.post('forgot_password.php', {'action': 'save', 'password': 'Driver9999', 'confirm_password': 'Driver9999'})
ok('a driver can reset too and the lock is cleared', C().login('drv001', 'Driver9999').status_code == 302)
sys.exit(0 if summary() else 1)
